{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The managed policy is attached directly to an IAM user, increasing the risk of permissions being retained or managed inconsistently. Assigning the policy through a group provides centralized access management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc3-passrole-policy-group" {
  name = "fn1-privesc3-passrole-policy-group"
}

resource "aws_iam_user_group_membership" "privesc3-passrole-user-membership" {
  user = aws_iam_user.fn1-privesc3-partial-user.name

  groups = [
    aws_iam_group.privesc3-passrole-policy-group.name,
  ]
}

resource "aws_iam_group_policy_attachment" "privesc3-passrole-user-attach-policy" {
  group      = aws_iam_group.privesc3-passrole-policy-group.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a group policy attachment and added the existing user to that group. The same managed policy remains assigned while access management is centralized through an IAM group."
}
